insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-ek-153","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"When every species in the cell reaction is in its standard state, $Q = 1$ and therefore","options":["$E = E^\\circ$","$E = 0$ always","$E = 0.059\\ \\mathrm{V}$","$E = -E^\\circ$"],"answer_index":0,"explanation":"The log term vanishes at $Q = 1$, recovering the standard EMF.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"nernst"},{"id":"che-ek-154","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A concentration cell that uses the same couple on both sides has","options":["$E^\\circ = 0$, but a non-zero $E$ if the two concentrations differ","$E^\\circ$ equal to twice a single-electrode potential","no possible EMF under any condition","$E$ independent of both concentrations"],"answer_index":0,"explanation":"The two standard potentials cancel. The remaining voltage comes only from the concentration (activity) ratio.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"nernst"},{"id":"che-ek-155","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"As the reaction quotient $Q$ of a galvanic cell increases, the cell EMF generally","options":["decreases","increases without limit","jumps discontinuously to $E^\\circ$","becomes independent of $n$"],"answer_index":0,"explanation":"$E = E^\\circ - (RT/nF)\\ln Q$, so a larger $Q$ reduces $E$. At equilibrium $Q = K$ and $E = 0$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"nernst"},{"id":"che-ek-156","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For the half-cell $\\mathrm{M}^{n+} + n\\,e^- \\rightarrow \\mathrm{M}(s)$, the Nernst expression at 298 K is","options":["$E = E^\\circ + (0.059/n)\\log[\\mathrm{M}^{n+}]$","$E = E^\\circ - (0.059/n)\\log[\\mathrm{M}^{n+}]$","$E = E^\\circ + 0.059\\,n\\,[\\mathrm{M}^{n+}]$","$E = (0.059/n)/[\\mathrm{M}^{n+}]$"],"answer_index":0,"explanation":"Solid metal has activity 1, so $Q = 1/[\\mathrm{M}^{n+}]$ and the sign of the log term flips.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"nernst"},{"id":"che-ek-157","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The integer $n$ that appears in the Nernst equation is the","options":["number of moles of electrons transferred in the balanced cell reaction","number of ions in the salt bridge","atomic number of the anode metal","order of the electrode reaction"],"answer_index":0,"explanation":"$n$ comes from the balanced redox equation (for Daniell, $n = 2$).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"nernst"},{"id":"che-ek-158","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"When a galvanic cell has run down to equilibrium, the Nernst voltage satisfies","options":["$E = 0$ and $Q = K$","$E = E^\\circ$ and $Q = 0$","$E = \\infty$","$E = -nF$"],"answer_index":0,"explanation":"No further driving force remains ($E = 0$), which forces $Q$ to equal the equilibrium constant $K$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"nernst"},{"id":"che-ek-159","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The potential of a hydrogen electrode at 298 K, $p_{\\mathrm{H_2}} = 1\\ \\mathrm{bar}$, varies with pH as","options":["$E = -0.059\\,\\mathrm{pH}$","$E = +0.059\\,\\mathrm{pH}$","$E = 0.059/\\mathrm{pH}$","$E = 1.23 - 0.059\\,\\mathrm{pH}$"],"answer_index":0,"explanation":"$E = 0.059\\log[\\mathrm{H}^+] = -0.059\\,\\mathrm{pH}$ when hydrogen is at unit pressure.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"nernst"},{"id":"che-ek-160","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Raising the concentration of a product ion in the cell reaction, other terms fixed, will","options":["lower the cell EMF","raise $E^\\circ$","leave both $E$ and $Q$ unchanged","reverse the definition of the anode"],"answer_index":0,"explanation":"Products appear in the numerator of $Q$. A larger $Q$ makes $(RT/nF)\\ln Q$ larger and $E$ smaller.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"nernst"},{"id":"che-ek-161","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Absolute temperature enters the Nernst equation because","options":["the $RT/nF$ prefactor, and therefore the size of the $\\log Q$ correction, depends on $T$","Faraday's constant itself is proportional to $T$","$n$ changes with temperature","standard potentials are defined only at 0 K"],"answer_index":0,"explanation":"At higher $T$ a given $Q$ shifts $E$ farther from $E^\\circ$. $E^\\circ$ itself may also change with $T$, but that is a separate effect.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"nernst"},{"id":"che-ek-162","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A Daniell cell with $E^\\circ = 1.10\\ \\mathrm{V}$ has $[\\mathrm{Zn^{2+}}] = 0.10\\ \\mathrm{M}$ and $[\\mathrm{Cu^{2+}}] = 1.0\\ \\mathrm{M}$. $E$ at 298 K is nearest","options":["$1.13\\ \\mathrm{V}$","$1.07\\ \\mathrm{V}$","$0.10\\ \\mathrm{V}$","$1.16\\ \\mathrm{V}$"],"answer_index":0,"explanation":"$E = 1.10 - (0.059/2)\\log(0.10/1.0) = 1.10 + 0.0295 = 1.13\\ \\mathrm{V}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"nernst"},{"id":"che-ek-163","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For $\\mathrm{Cu}|\\mathrm{Cu^{2+}}(0.010\\ \\mathrm{M})||\\mathrm{Cu^{2+}}(1.0\\ \\mathrm{M})|\\mathrm{Cu}$ at 298 K the EMF is","options":["$0.059\\ \\mathrm{V}$","$0.029\\ \\mathrm{V}$","$0.118\\ \\mathrm{V}$","$0.34\\ \\mathrm{V}$"],"answer_index":0,"explanation":"$E^\\circ = 0$ and $n = 2$, so $E = (0.059/2)\\log(1.0/0.010) = 0.0295 \\times 2 = 0.059\\ \\mathrm{V}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"nernst"},{"id":"che-ek-164","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Take $E^\\circ(\\mathrm{Zn^{2+}/Zn}) = -0.76\\ \\mathrm{V}$. At $[\\mathrm{Zn^{2+}}] = 0.010\\ \\mathrm{M}$ and 298 K the zinc electrode potential is nearest","options":["$-0.82\\ \\mathrm{V}$","$-0.70\\ \\mathrm{V}$","$-0.76\\ \\mathrm{V}$","$+0.76\\ \\mathrm{V}$"],"answer_index":0,"explanation":"$E = -0.76 + (0.059/2)\\log(0.010) = -0.76 + 0.0295\\times(-2) = -0.82\\ \\mathrm{V}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"nernst"},{"id":"che-ek-165","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Starting from a standard Daniell cell, diluting only the Cu$^{2+}$ half-cell tenfold at 298 K changes $E$ by about","options":["a decrease of $0.030\\ \\mathrm{V}$","an increase of $0.059\\ \\mathrm{V}$","a decrease of $0.76\\ \\mathrm{V}$","no change, because $E^\\circ$ is fixed"],"answer_index":0,"explanation":"$Q$ rises by 10, so $\\Delta E = -(0.059/2)\\log 10 \\approx -0.030\\ \\mathrm{V}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"nernst"},{"id":"che-ek-166","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A hydrogen electrode ($p_{\\mathrm{H_2}} = 1\\ \\mathrm{bar}$) dipping into $0.0010\\ \\mathrm{M}$ HCl at 298 K develops a potential of","options":["$-0.177\\ \\mathrm{V}$","$0.000\\ \\mathrm{V}$","$-0.059\\ \\mathrm{V}$","$+0.177\\ \\mathrm{V}$"],"answer_index":0,"explanation":"$[\\mathrm{H}^+] = 10^{-3}$, so $E = 0.059\\log(10^{-3}) = -0.177\\ \\mathrm{V}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"nernst"},{"id":"che-ek-167","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For $\\mathrm{Zn}|\\mathrm{Zn^{2+}}(0.10\\ \\mathrm{M})||\\mathrm{Cu^{2+}}(0.0010\\ \\mathrm{M})|\\mathrm{Cu}$ with $E^\\circ = 1.10\\ \\mathrm{V}$, $E$ at 298 K is","options":["$1.041\\ \\mathrm{V}$","$1.159\\ \\mathrm{V}$","$0.041\\ \\mathrm{V}$","$1.10\\ \\mathrm{V}$"],"answer_index":0,"explanation":"$Q = 0.10/0.0010 = 100$; $E = 1.10 - (0.059/2)\\log 100 = 1.10 - 0.059 = 1.041\\ \\mathrm{V}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"nernst"},{"id":"che-ek-168","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A Cu concentration cell shows $E = 0.0295\\ \\mathrm{V}$ at 298 K. The ratio $[\\mathrm{Cu^{2+}}]_{\\mathrm{cathode}}/[\\mathrm{Cu^{2+}}]_{\\mathrm{anode}}$ is","options":["10","2","100","0.10"],"answer_index":0,"explanation":"$E = (0.059/2)\\log(c_c/c_a) = 0.0295$ implies $\\log(c_c/c_a) = 1$, so the concentration ratio is 10.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"nernst"},{"id":"che-ek-169","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Faraday's first law of electrolysis states that the mass deposited is proportional to the","options":["quantity of electricity passed through the electrolyte","square of the applied voltage only","volume of the voltameter","atmospheric pressure in the laboratory"],"answer_index":0,"explanation":"$m = ZQ = ZIt$. Charge (current × time) fixes how much material is liberated.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday"},{"id":"che-ek-170","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Faraday's second law compares two electrolytes carrying the same charge and says the liberated masses are proportional to their","options":["chemical equivalent masses (molar mass / n-factor)","densities in the solid state","boiling points","specific conductivities"],"answer_index":0,"explanation":"Equal charge liberates equal numbers of equivalents, so $m_1/m_2 = E_1/E_2$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday"},{"id":"che-ek-171","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"One faraday of charge liberates from an electrolyte","options":["one gram-equivalent of the substance","one gram-molecule regardless of $n$","exactly one gram of any metal","22.4 L of every gas at STP"],"answer_index":0,"explanation":"1 F deposits 1 equivalent: 108 g Ag, 31.75 g Cu, 9 g Al, 11.2 L H$_2$ at STP, and so on.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday"},{"id":"che-ek-172","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The charge carried by one mole of electrons is called","options":["one faraday","one ampere","one siemens","one equivalent conductivity"],"answer_index":0,"explanation":"$F = N_A e \\approx 96500\\ \\mathrm{C\\ mol^{-1}}$. It is the charge needed to reduce one mole of a univalent ion.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
insert into question_pyq_meta (question_id, appear_count, years, exams, verified) select question_id, appear_count, years, exams, verified from jsonb_to_recordset($meta$[{"question_id":"che-ek-153","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-154","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-155","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-156","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-157","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-158","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-159","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-160","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-161","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-162","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-163","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-164","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-165","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-166","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-167","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-168","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-169","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-170","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-171","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-172","appear_count":0,"years":[],"exams":[],"verified":false}]$meta$::jsonb) as t(question_id text, appear_count int, years int[], exams text[], verified boolean) on conflict (question_id) do 